test_snippets.cpp:
void check(Solution& solution) {
    assert(solution.removeComments({"/* This is a comment // with a line comment inside the block comment */", "int x = 10;", "cout << \"Hello World\";", "}"}) == vector<int>{'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"int main() {", "    printf(\"Hello World\"); // This is a comment", "}" }) == vector<int>{'int main() {', '    printf("Hello World"); ', '}'});
    assert(solution.removeComments({"int main() {", "/* Start of block comment \" /* still in block comment */ end of block comment */", "int x = 10;", "cout << \"Hello World\";", "}"}) == vector<int>{'int main() {', ' end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"int x = 10;", "// This is a line comment", "int y = 20;" }) == vector<int>{'int x = 10;', 'int y = 20;'});
    assert(solution.removeComments({"/* This is a block comment", "and this is the second line", "and the third line */", "int z = 30;" }) == vector<int>{'int z = 30;'});
    assert(solution.removeComments({"/*", "block comment", "*/" }) == vector<int>{});
    assert(solution.removeComments({"// This is a single line comment", "int x = 10; // this is also a comment", "/* This is a block comment", "   that continues", "   on multiple lines */", "int y = 20;" }) == vector<int>{'int x = 10; ', 'int y = 20;'});
    assert(solution.removeComments({"void func() {", "/* This is a ", "multiline comment */", "int x = 10;", "// This is a single line comment", "}"}) == vector<int>{'void func() {', 'int x = 10;', '}'});
    assert(solution.removeComments({"void fun() {", "   /* Multi", "line", "comment */", "   int k = 1;", "}" }) == vector<int>{'void fun() {', '   ', '   int k = 1;', '}'});
    assert(solution.removeComments({"/* comment /* nested comment */ end of comment */", "int x = 1;" }) == vector<int>{' end of comment */', 'int x = 1;'});
    assert(solution.removeComments({"#include <iostream>", "/* Start of block comment", "still in block comment", "end of block comment */", "int main() {", "cout << \"Hello World\";", "// This line should be printed", "}"}) == vector<int>{'#include <iostream>', 'int main() {', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"/*Test program */", "int main()", "{ ", "  // variable declaration ", "int a, b, c;", "/* This is a test", "   multiline  ", "   comment for ", "   testing */", "a = b + c;", "}"}) == vector<int>{'int main()', '{ ', '  ', 'int a, b, c;', 'a = b + c;', '}'});
    assert(solution.removeComments({"int main() {", "int x = 10; // This is a line comment", "cout << \"Hello World\";", "}"}) == vector<int>{'int main() {', 'int x = 10; ', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"int x = 10;", "// This is a line comment", "x++;", "/* This is a block comment", "x--;", "*/", "return x;" }) == vector<int>{'int x = 10;', 'x++;', 'return x;'});
    assert(solution.removeComments({"a/*comment", "line", "more_comment*/b"}) == vector<int>{'ab'});
    assert(solution.removeComments({"/*Hello", "World*/", "int main()" }) == vector<int>{'int main()'});
    assert(solution.removeComments({"int main()", "{", "/* This is a test comment", "with multiple", "lines */", "return 0;", "}" }) == vector<int>{'int main()', '{', 'return 0;', '}'});
    assert(solution.removeComments({"void f() {", "/* single line block comment */", "}" }) == vector<int>{'void f() {', '}'});
    assert(solution.removeComments({"class Solution {", "public:", "    vector<int> twoSum(vector<int>& nums, int target) {", "        /*", "        for (int i = 0; i < nums.size(); i++) {", "            for (int j = i + 1; j < nums.size(); j++) {", "                if (nums{i} + nums{j} == target) {", "                    return {i, j};", "                }", "            }", "        }", "        */", "        return {};", "    }", "};"}) == vector<int>{'class Solution {', 'public:', '    vector<int> twoSum(vector<int>& nums, int target) {', '        ', '        return {};', '    }', '};'});
    assert(solution.removeComments({"int x = 1; // single line comment", "/* int y = 2; */", "int z = 3;" }) == vector<int>{'int x = 1; ', 'int z = 3;'});
    assert(solution.removeComments({"// comment", "// another comment", "int x = 1;" }) == vector<int>{'int x = 1;'});
    assert(solution.removeComments({"/* Comment \" continues on next line", "and ends here */", "int a = 1;", "// Single line comment", "int b = 2;", "int c = 3;"}) == vector<int>{'int a = 1;', 'int b = 2;', 'int c = 3;'});
    assert(solution.removeComments({"/* This is a block comment that includes", "a line with // single line comment inside it", "*/", "int a = 10;", "int b = 20;", "/* Another block comment that includes", "a line with // single line comment inside it", "*/", "int c = 30;"}) == vector<int>{'int a = 10;', 'int b = 20;', 'int c = 30;'});
    assert(solution.removeComments({"int main() {", "    // Start of line comment \" /* this is not a comment \" end of line comment", "    int x = 1;", "    /* Start of block comment \" // still in block comment \" */", "    int y = 2;", "    printf(\"Result: %d\", x + y);", "}"}) == vector<int>{'int main() {', '    ', '    int x = 1;', '    ', '    int y = 2;', '    printf("Result: %d", x + y);', '}'});
    assert(solution.removeComments({"int main() {", "    int x = 1;", "    /* Start of block comment \" // this is not a comment \" */", "    int y = 2;", "    // This is a line comment \" /* this is not a comment \" end of line comment", "    printf(\"Result: %d\", x + y);", "    /* Another block comment \" // still in block comment \" end of block comment */", "}"}) == vector<int>{'int main() {', '    int x = 1;', '    ', '    int y = 2;', '    ', '    printf("Result: %d", x + y);', '    ', '}'});
    assert(solution.removeComments({"int main() {", "/* Block comment starts here", "int x = 10;", "/* Nested comment \" /* still in nested comment */ \" end of nested comment */", "int y = 20;", "*/ int z = 30;", "// End of file comment", "}"}) == vector<int>{'int main() {', ' " end of nested comment */', 'int y = 20;', '*/ int z = 30;', '}'});
    assert(solution.removeComments({"/* Start of block comment \n /* nested block comment */ still in block comment */", "int x = 10;"}) == vector<int>{' still in block comment */', 'int x = 10;'});
    assert(solution.removeComments({"/* Start of block comment ", "/* Nested block comment ", "*/", "End of nested block comment */", "int x = 40;", "// Line comment /* not a block comment */"}) == vector<int>{'End of nested block comment */', 'int x = 40;'});
    assert(solution.removeComments({"void func() {", "int x = 1;", "/* Comment with newline character \n */", "int y = 2;", "}"}) == vector<int>{'void func() {', 'int x = 1;', 'int y = 2;', '}'});
    assert(solution.removeComments({"/* comment with \"escaped quotes\" inside block comment */", "int x = 1;", "// Single line comment after block comment", "/* Another block comment \"with quotes\" inside */", "int y = 2;", "}"}) == vector<int>{'int x = 1;', 'int y = 2;', '}'});
    assert(solution.removeComments({"/* This is a comment /* nested block comment */ end of comment */", "int x = 1;", "// Single-line comment after block comment", "/* Another block comment */ int y = 2;"}) == vector<int>{' end of comment */', 'int x = 1;', ' int y = 2;'});
    assert(solution.removeComments({"/* Comment spanning multiple lines", "including quotes \" and other symbols /* nested */", "still in block comment \" end block comment */", "int x = 1;", "cout << \"Hello World\";" }) == vector<int>{'still in block comment " end block comment */', 'int x = 1;', 'cout << "Hello World";'});
    assert(solution.removeComments({"/* comment with end of line comment // inside block comment */", "int q = 8;", "int r = 9;", "/* comment with // nested line comment /* nested block comment */ inside block comment */", "int s = 10;" }) == vector<int>{'int q = 8;', 'int r = 9;', ' inside block comment */', 'int s = 10;'});
    assert(solution.removeComments({"int main() {", "/* Comment with \"quoted\" text inside */", "int x = 20;", "/* Another /* nested */ comment */", "return x;", "}"}) == vector<int>{'int main() {', 'int x = 20;', ' comment */', 'return x;', '}'});
    assert(solution.removeComments({"void example() {", "/* This is a block comment /* with another comment inside */ and continues here */", "int a = 10;", "cout << \"Value: \" << a;", "// Single line comment after block comment", "}"}) == vector<int>{'void example() {', ' and continues here */', 'int a = 10;', 'cout << "Value: " << a;', '}'});
    assert(solution.removeComments({"class MyClass {", "    // This is a single line comment", "    int a;", "    /* This is a block comment ", "       int b;", "       // Another single line comment", "    */", "    int c;", "}"}) == vector<int>{'class MyClass {', '    ', '    int a;', '    ', '    int c;', '}'});
    assert(solution.removeComments({"/* This is a block comment that spans", "multiple lines and includes", "a single line comment // inside it */", "int z = 30;", "// This is a single line comment", "}"}) == vector<int>{'int z = 30;', '}'});
    assert(solution.removeComments({"/* Comment before code", "int x = 1;", "/* Comment after code", "int y = 2;", "// Single line comment", "int z = 3;", "/* Comment after last line */"}) == vector<int>{});
    assert(solution.removeComments({"void func() {", "int x = 10;", "/* Start of block comment ", "int y = 20;", "int z = 30;", "}*/"}) == vector<int>{'void func() {', 'int x = 10;'});
    assert(solution.removeComments({"int func() {", "if (x < 0) /* This is a block comment */ {", "return x;", "} else {", "return -x;", "}", "/* Another comment \" with quotes \" inside */", "}"}) == vector<int>{'int func() {', 'if (x < 0)  {', 'return x;', '} else {', 'return -x;', '}', '}'});
    assert(solution.removeComments({"/* Comment spanning", "multiple lines with newline character \n and /* nested */ comment \n end comment */", "int x = 1;", "cout << \"Hello World\";" }) == vector<int>{' comment \n end comment */', 'int x = 1;', 'cout << "Hello World";'});
    assert(solution.removeComments({"int main() {", "/* Start of block comment \" /* nested block comment \" still in block comment */", "int x = 10;", "cout << \"Hello World\";", "}"}) == vector<int>{'int main() {', 'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"/* comment with // nested line comment inside block comment /* nested block comment */ inside block comment */", "int x = 15;", "int y = 16;" }) == vector<int>{' inside block comment */', 'int x = 15;', 'int y = 16;'});
    assert(solution.removeComments({"/* Comment spanning multiple lines", "including quotes \" and other symbols /* nested /* deeply nested */ end nested comment */", "still in block comment \" end block comment */", "int x = 1;", "cout << \"Hello World\";" }) == vector<int>{' end nested comment */', 'still in block comment " end block comment */', 'int x = 1;', 'cout << "Hello World";'});
    assert(solution.removeComments({"// Single-line comment", "/* Multi-line comment starts here", "int x = 10;", "/* Nested comment */", "int y = 20;", "*/ int z = 30;", "// End of file comment", "/* Last comment */"}) == vector<int>{'int y = 20;', '*/ int z = 30;'});
    assert(solution.removeComments({"int main() {", "    /* Start of a block comment ", "       /* Nested block comment */", "    */", "    int x = 10;", "    // This is a single line comment", "}"}) == vector<int>{'int main() {', '    ', '    */', '    int x = 10;', '    ', '}'});
    assert(solution.removeComments({"/* Start of block comment ", "void func() {", "int x = 10;", "} /* End of block comment */"}) == vector<int>{});
    assert(solution.removeComments({"/* start of block comment", "with multiple lines", "and /* nested block comment */", "inside it", "end of block comment */", "int t = 11;", "int u = 12;" }) == vector<int>{'inside it', 'end of block comment */', 'int t = 11;', 'int u = 12;'});
    assert(solution.removeComments({"/* comment with // nested line comment */", "int o = 6;", "/* comment with /* nested block comment */ inside it */", "int p = 7;" }) == vector<int>{'int o = 6;', ' inside it */', 'int p = 7;'});
    assert(solution.removeComments({"int main() {", "int x = 10;", "/* Comment with special characters !@#$%^&*()_+*/", "int y = 20;", "}"}) == vector<int>{'int main() {', 'int x = 10;', 'int y = 20;', '}'});
    assert(solution.removeComments({"/* Comment with /* deep nesting /* even deeper */ still deep */ end of deep nesting */", "int x = 80;", "int main() {", "int y = 90;", "return x + y;", "}"}) == vector<int>{' still deep */ end of deep nesting */', 'int x = 80;', 'int main() {', 'int y = 90;', 'return x + y;', '}'});
    assert(solution.removeComments({"int main() {", "/* Block comment \" /* nested block comment \" end of nested block comment */ end of block comment */", "int x = 10;", "cout << \"Hello World\";", "}"}) == vector<int>{'int main() {', ' end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"// This is a single line comment", "int a = 1;", "// Another single line comment", "int b = 2;", "// Last single line comment"}) == vector<int>{'int a = 1;', 'int b = 2;'});
    assert(solution.removeComments({"int main() {", "if (true) {", "// This is a comment inside a block", "int x = 1;", "}", "/* Another block comment \" end of block comment */", "int y = 2;", "}"}) == vector<int>{'int main() {', 'if (true) {', 'int x = 1;', '}', 'int y = 2;', '}'});
    assert(solution.removeComments({"int main() {", "/* Start of block comment", "which continues", "and includes \"quotes\" inside", "*/", "int x = 10;", "// This is a single line comment after block comment", "cout << \"Value: \" << x;", "}"}) == vector<int>{'int main() {', 'int x = 10;', 'cout << "Value: " << x;', '}'});
    assert(solution.removeComments({"/* This is a block comment \" // this is not a comment \" */", "int x = 1;", "/* another block comment \" // still in block comment \" */", "int y = 2;", "printf(\"Result: %d\", x + y);"}) == vector<int>{'int x = 1;', 'int y = 2;', 'printf("Result: %d", x + y);'});
    assert(solution.removeComments({"/* This is a comment /* nested block comment */ end of comment */", "int x = 1;", "// Single-line comment after block comment", "/* Another block comment \" \" */ int y = 2;", "int z = 3;"}) == vector<int>{' end of comment */', 'int x = 1;', ' int y = 2;', 'int z = 3;'});
    assert(solution.removeComments({"void foo() {", "/* Multi-line comment starts here", "and continues", "on multiple lines */", "int y = 30;", "// Another single-line comment", "}"}) == vector<int>{'void foo() {', 'int y = 30;', '}'});
    assert(solution.removeComments({"/* Opening block comment", "int x = 50;", "int y = 60;", "// Line comment inside block comment", "*/", "int z = 70;", "/* Another block comment \" with quotes \" inside */", "}"}) == vector<int>{'int z = 70;', '}'});
    assert(solution.removeComments({"// single line comment /* block comment on same line */", "/* block comment // single line comment inside block comment */", "int v = 13;" }) == vector<int>{'int v = 13;'});
    assert(solution.removeComments({"int main() {", "int x = 1;", "/* Comment with newline character \n and /* nested */ comment */", "int y = 2;", "}"}) == vector<int>{'int main() {', 'int x = 1;', ' comment */', 'int y = 2;', '}'});
    assert(solution.removeComments({"int main() {", "    /* Start of block comment", "    // Single line comment inside block comment", "    end of block comment */", "    int x = 10;", "    // This is a single line comment", "}"}) == vector<int>{'int main() {', '    ', '    int x = 10;', '    ', '}'});
    assert(solution.removeComments({"void foo() {", "    /* This is a block comment that ends on the same line */ int y = 20;", "    // This is a single line comment", "}"}) == vector<int>{'void foo() {', '     int y = 20;', '    ', '}'});
    assert(solution.removeComments({"/* Comment line 1", "Comment line 2", "Comment line 3 */", "int a = 1;", "int b = 2;", "int c = 3;"}) == vector<int>{'int a = 1;', 'int b = 2;', 'int c = 3;'});
    assert(solution.removeComments({"/* Start of block comment", "int x = 110;", "// Line comment inside block comment", "int y = 120;", "*/", "int z = 130;", "/* Another block comment", "/* Nested block comment */", "End of nested block comment */", "return x + y + z;", "}"}) == vector<int>{'int z = 130;', 'End of nested block comment */', 'return x + y + z;', '}'});
    assert(solution.removeComments({"/* Start of block comment \n /* nested block comment \n still in block comment */", "int x = 10;"}) == vector<int>{'int x = 10;'});
    assert(solution.removeComments({"/* Start of block comment \" with quotes \" inside /* nested block comment \" with quotes \" inside */ end of nested block comment \" with quotes \" inside */", "int main() {", "int x = 140;", "int y = 150;", "// Line comment \" with quotes \" inside block comment", "int z = 160;", "return x + y + z;", "}"}) == vector<int>{' end of nested block comment " with quotes " inside */', 'int main() {', 'int x = 140;', 'int y = 150;', 'int z = 160;', 'return x + y + z;', '}'});
    assert(solution.removeComments({"int main() {", "// Line comment \" // still in line comment \" end of line comment ", "int x = 10;", "}"}) == vector<int>{'int main() {', 'int x = 10;', '}'});
    assert(solution.removeComments({"int main() {", "/* Start of block comment /* still in block comment */ end of block comment */", "int x = 10;", "// Single line comment after block comment", "cout << \"Hello World\";", "}"}) == vector<int>{'int main() {', ' end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"/* comment with /* nested block comment /* another nested block comment */ end of inner block comment */ end of outer block comment */", "int w = 14;" }) == vector<int>{' end of inner block comment */ end of outer block comment */', 'int w = 14;'});
    assert(solution.removeComments({"/* Multiline comment \"with quotes\" inside /* nested comment */ still inside */", "int main() {", "/* Another comment \" with quotes \" and /* nested */ */", "int z = 100;", "return z;", "}"}) == vector<int>{' still inside */', 'int main() {', ' */', 'int z = 100;', 'return z;', '}'});
    assert(solution.removeComments({"void func() {", "/* Start of block comment ", "int x = 10;", "} // End of function ", "*/"}) == vector<int>{'void func() {'});
    assert(solution.removeComments({"/* comment /* nested /* deeply nested */ comment */ end */", "int x = 1;", "// single line comment after block comment"}) == vector<int>{' comment */ end */', 'int x = 1;'});
    assert(solution.removeComments({"int main() {", "/* Block comment \" /* nested comment */ \" end of block comment */", "int x = 10;", "cout << \"Hello World\";", "// Single-line comment", "}"}) == vector<int>{'int main() {', ' " end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}'});
    assert(solution.removeComments({"int main() {", "    if (x > 0) {", "        /* Start of block comment \" /* still in block comment */ \" end of block comment */", "        printf(\"Hello World\");", "    }", "}"}) == vector<int>{'int main() {', '    if (x > 0) {', '         " end of block comment */', '        printf("Hello World");', '    }', '}'});
    assert(solution.removeComments({"/* Comment with \"escaped quote\" inside */", "int x = 10;"}) == vector<int>{'int x = 10;'});
    assert(solution.removeComments({"int main() {", "int x = 1;", "// This is a comment \" /* this should be ignored */ end comment", "int y = 2;", "/* This is a block comment \" /* nested */ end block comment */", "int z = 3;", "}"}) == vector<int>{'int main() {', 'int x = 1;', 'int y = 2;', ' end block comment */', 'int z = 3;', '}'});
    assert(solution.removeComments({"void func() {", "/* This is a ", "multiline comment /* nested comment */", "end of block comment */", "int x = 10;", "// This is a single line comment /* this should be ignored */", "}"}) == vector<int>{'void func() {', 'end of block comment */', 'int x = 10;', '}'});
    assert(solution.removeComments({"void function() {", "int i = 0;", "/* start of block comment", "int j = 1;", "// single line comment inside block comment", "int k = 2;", "end of block comment */", "int l = 3;", "}" }) == vector<int>{'void function() {', 'int i = 0;', 'int l = 3;', '}'});
    assert(solution.removeComments({"// Line comment \" // still a line comment \"", "int main() {", "int x = 30;", "/* Multiline \" comment \" block ", "with line continuation ", "*/", "return x;", "}"}) == vector<int>{'int main() {', 'int x = 30;', 'return x;', '}'});
    assert(solution.removeComments({"int main() {", "    /* Start of block comment \" /* still in block comment \" */ end of block comment */", "    int x = 1;", "    if (x > 0) {", "        // This is a line comment \" /* this is not a comment \" end of line comment", "        int y = 2;", "        printf(\"Result: %d\", x + y);", "    }", "}"}) == vector<int>{'int main() {', '     end of block comment */', '    int x = 1;', '    if (x > 0) {', '        ', '        int y = 2;', '        printf("Result: %d", x + y);', '    }', '}'});
    assert(solution.removeComments({"/* Multi", "line", "block", "comment */", "int main() {", "return 0;", "}"}) == vector<int>{'int main() {', 'return 0;', '}'});
    assert(solution.removeComments({"/* Comment before code \" // this is not a comment \" */", "#include <iostream>", "using namespace std;", "int main() {", "    int x = 1;", "    /* Start of block comment \" /* still in block comment \" end of block comment */", "    int y = 2;", "    // This is a line comment \" /* this is not a comment \" end of line comment", "    printf(\"Result: %d\", x + y);", "}"}) == vector<int>{'#include <iostream>', 'using namespace std;', 'int main() {', '    int x = 1;', '    ', '    int y = 2;', '    ', '    printf("Result: %d", x + y);', '}'});
    assert(solution.removeComments({"/* This comment ", "spans ", "multiple lines */", "int main() {", "    int x = 10;", "    /* Another block comment ", "    spanning ", "    multiple lines */", "    int y = 20;", "}"}) == vector<int>{'int main() {', '    int x = 10;', '    ', '    int y = 20;', '}'});
    assert(solution.removeComments({"/* Start of block comment ", "/* nested block comment ", "end of nested block comment */", "end of block comment */", "int x = 1;", "cout << \"Hello World\";" }) == vector<int>{'end of block comment */', 'int x = 1;', 'cout << "Hello World";'});
    assert(solution.removeComments({"/* Start of block comment \n // line comment inside block comment \n still in block comment */", "int x = 10;"}) == vector<int>{'int x = 10;'});
    assert(solution.removeComments({"/* Line 1", "Line 2 still in comment", "Line 3 // inline comment after block comment", "Line 4 */ int x = 20;", "// End of file comment"}) == vector<int>{' int x = 20;'});
    assert(solution.removeComments({"/* Comment before line */ int x = 10;", "int y = 20; /* Comment after line */", "int z = 30;"}) == vector<int>{' int x = 10;', 'int y = 20; ', 'int z = 30;'});
    assert(solution.removeComments({"/* Line 1 comment", "/* Nested comment starts here", "and continues here */", "Back to outer comment */", "int z = 40;", "// End of file comment"}) == vector<int>{'Back to outer comment */', 'int z = 40;'});
    assert(solution.removeComments({"int main() {", "// Single line comment before block comment", "/* Start of block comment", "which continues", "and includes \"quotes\" inside", "*/", "int x = 10;", "cout << \"Value: \" << x;", "/* Another block comment \"with quotes\" inside */", "int y = 2;", "}"}) == vector<int>{'int main() {', 'int x = 10;', 'cout << "Value: " << x;', 'int y = 2;', '}'});
    assert(solution.removeComments({"/* comment starts", "and continues here", "and continues here too */", "int y = 20;", "/* comment ends here", "and here too */", "int z = 30;" }) == vector<int>{'int y = 20;', 'int z = 30;'});
