    assert Arrays.equals(solution.removeComments(new int[]{"// Start of file comment", "/* Multi-line comment starts here", "int x = 10;", "/* Nested comment */", "int y = 20;", "*/ int z = 30;", "// End of file comment"}), new int[]{'int y = 20;', '*/ int z = 30;'});
