    assert Arrays.equals(solution.removeComments(new int[]{"int main() {", "/* This is a block comment", "which spans multiple lines \" /* still in block comment */ \" and continues here", "*/", "int a = 10;", "// This is a single line comment", "cout << \"Output: \" << a;", "}"}), new int[]{'int main() {', ' " and continues here', '*/', 'int a = 10;', 'cout << "Output: " << a;', '}'});
