function check(candidate: Function): void {
    console.assert(JSON.stringify(candidate(["/* This is a comment // with a line comment inside the block comment */", "int x = 10;", "cout << \"Hello World\";", "}"])) === JSON.stringify(['int x = 10;', 'cout << "Hello World";', '}']));
    console.assert(JSON.stringify(candidate(["int main() {", "    printf(\"Hello World\"); // This is a comment", "}" ])) === JSON.stringify(['int main() {', '    printf("Hello World"); ', '}']));
    console.assert(JSON.stringify(candidate(["int main() {", "/* Start of block comment \" /* still in block comment */ end of block comment */", "int x = 10;", "cout << \"Hello World\";", "}"])) === JSON.stringify(['int main() {', ' end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}']));
    console.assert(JSON.stringify(candidate(["int x = 10;", "// This is a line comment", "int y = 20;" ])) === JSON.stringify(['int x = 10;', 'int y = 20;']));
    console.assert(JSON.stringify(candidate(["/* This is a block comment", "and this is the second line", "and the third line */", "int z = 30;" ])) === JSON.stringify(['int z = 30;']));
    console.assert(JSON.stringify(candidate(["/*", "block comment", "*/" ])) === JSON.stringify([]));
    console.assert(JSON.stringify(candidate(["// This is a single line comment", "int x = 10; // this is also a comment", "/* This is a block comment", "   that continues", "   on multiple lines */", "int y = 20;" ])) === JSON.stringify(['int x = 10; ', 'int y = 20;']));
    console.assert(JSON.stringify(candidate(["void func() {", "/* This is a ", "multiline comment */", "int x = 10;", "// This is a single line comment", "}"])) === JSON.stringify(['void func() {', 'int x = 10;', '}']));
    console.assert(JSON.stringify(candidate(["void fun() {", "   /* Multi", "line", "comment */", "   int k = 1;", "}" ])) === JSON.stringify(['void fun() {', '   ', '   int k = 1;', '}']));
    console.assert(JSON.stringify(candidate(["/* comment /* nested comment */ end of comment */", "int x = 1;" ])) === JSON.stringify([' end of comment */', 'int x = 1;']));
    console.assert(JSON.stringify(candidate(["#include <iostream>", "/* Start of block comment", "still in block comment", "end of block comment */", "int main() {", "cout << \"Hello World\";", "// This line should be printed", "}"])) === JSON.stringify(['#include <iostream>', 'int main() {', 'cout << "Hello World";', '}']));
