    console.assert(JSON.stringify(candidate(["int main()", "{", "/* This is a test comment", "with multiple", "lines */", "return 0;", "}" ])) === JSON.stringify(['int main()', '{', 'return 0;', '}']));
    console.assert(JSON.stringify(candidate(["void f() {", "/* single line block comment */", "}" ])) === JSON.stringify(['void f() {', '}']));
