fn check(candidate: fn(Vec<i32>, i32) -> Vec<i32>) {
    assert_eq!(candidate(vec!["/* This is a comment // with a line comment inside the block comment */", "int x = 10;", "cout << \"Hello World\";", "}"]), vec!['int x = 10;', 'cout << "Hello World";', '}']);
    assert_eq!(candidate(vec!["int main() {", "    printf(\"Hello World\"); // This is a comment", "}" ]), vec!['int main() {', '    printf("Hello World"); ', '}']);
    assert_eq!(candidate(vec!["int main() {", "/* Start of block comment \" /* still in block comment */ end of block comment */", "int x = 10;", "cout << \"Hello World\";", "}"]), vec!['int main() {', ' end of block comment */', 'int x = 10;', 'cout << "Hello World";', '}']);
    assert_eq!(candidate(vec!["int x = 10;", "// This is a line comment", "int y = 20;" ]), vec!['int x = 10;', 'int y = 20;']);
    assert_eq!(candidate(vec!["/* This is a block comment", "and this is the second line", "and the third line */", "int z = 30;" ]), vec!['int z = 30;']);
    assert_eq!(candidate(vec!["/*", "block comment", "*/" ]), vec![]);
