    assert_eq!(candidate(vec!["void func() {", "/* This is a ", "multiline comment */", "int x = 10;", "// This is a single line comment", "}"]), vec!['void func() {', 'int x = 10;', '}']);
    assert_eq!(candidate(vec!["void fun() {", "   /* Multi", "line", "comment */", "   int k = 1;", "}" ]), vec!['void fun() {', '   ', '   int k = 1;', '}']);
